package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaIdDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_yamani_hajar" to DuaText("Antara Rukn Yamani dan Hajar Aswad", "Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami dari siksa Neraka.", "Dalam tawaf, antara Sudut Yaman dan Hajar Aswad.", "Nabi ﷺ membacakan ini di tempat ini dalam tawaf."),
        "dua_safa_marwa" to DuaText("Di Safa dan Marwah", "Tidak ada yang berhak disembah kecuali Allah, sendiri, tanpa sekutu. Milik-Nya kekuasaan dan milik-Nya pujian, dan Dia Mahakuasa atas segala sesuatu. Tidak ada yang berhak disembah kecuali Allah saja; Dia memenuhi janji-Nya, membantu hamba-Nya dan sendirian mengalahkan sekutu.", "Mendaki Safa dan menghadap kiblat (tiga kali).", "Dzikir Nabi ﷺ tentang Safa dan Marwah."),
        "dua_arafah" to DuaText("Doa Terbaik di Hari Arafah", "Tidak ada yang berhak disembah kecuali Allah, sendiri, tanpa sekutu. Milik-Nya kekuasaan dan milik-Nya pujian, dan Dia Mahakuasa atas segala sesuatu.", "Hari Arafah - doa terbaik.", "Doa yang paling baik adalah doa di hari Arafah, dan kata-kata yang paling baik adalah doa tersebut."),
        "dua_takbeer_tashreeq" to DuaText("Takbir-e-Tashreeq", "Allah Maha Besar, Allah Maha Besar. Tidak ada Tuhan selain Allah. Allah Maha Besar, Allah Maha Besar, dan segala puji bagi Allah.", "Setiap habis salat wajib mulai dari Subuh tanggal 9 Dzulhijjah hingga Ashar tanggal 13 Dzulhijjah.", "Diriwayatkan dari Ali dan Ibnu Mas'ud (RA) — wajib menurut Hanafi."),
        "dua_zamzam" to DuaText("Minum Zamzam", "Ya Allah, aku memohon kepada-Mu ilmu yang bermanfaat, rezeki yang melimpah, dan obat dari segala penyakit.", "Saat meminum Zamzam, doakan apa pun yang Anda inginkan.", "Zamzam itu untuk diminum apa saja (Ibnu Majah 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("Merefleksikan Penciptaan", "Ya Tuhan kami, Engkau tidak menciptakan semua ini dengan sia-sia. Maha Suci Engkau, lindungilah kami dari siksa api neraka.", "Doa orang-orang yang merenungkan penciptaan langit dan bumi.", "Doa orang yang berakal (ulul-albab)."),
        "dua_q_sami_na_munadiyan" to DuaText("Kami Mendengar Panggilan untuk Iman", "Ya Tuhan kami, kami mendengar seorang pemanggil berseru kepada iman, berkata 'Percayalah kepada Tuhanmu', dan kami beriman. Ya Tuhan kami, ampunilah dosa kami, hapuskan kesalahan kami dan matikan kami bersama orang-orang yang bertakwa.", "Doa untuk iman dan kematian di antara orang-orang saleh.", "Doa untuk pengampunan dan akhir yang baik."),
        "dua_q_atina_ma_waadtana" to DuaText("Berikan Kami Apa yang Anda Janjikan", "Ya Tuhan kami, berilah kami apa yang Engkau janjikan kepada kami melalui rasul-rasul-Mu dan janganlah kami mempermalukan kami di hari kiamat. Sesungguhnya Engkau tidak mengingkari janji-Mu.", "Berlindung dari aib di hari kiamat.", "Mencari kehormatan di akhirat."),
        "dua_q_israfana" to DuaText("Maafkan Kelebihan Kami", "Ya Tuhan kami, ampunilah kami atas dosa-dosa kami dan kelebihan kami dalam urusan kami, kuatkan kaki kami dan bantulah kami melawan orang-orang kafir.", "Doa para sahabat Nabi terdahulu.", "Doa untuk ketabahan dan pengampunan."),
        "dua_q_jamiun_nas" to DuaText("Anda Akan Mengumpulkan Umat Manusia", "Ya Tuhan kami, Sesungguhnya Engkau akan mengumpulkan manusia pada hari yang tidak ada keraguannya. Sesungguhnya Allah tidak mengingkari janji-Nya.", "Menegaskan kepastian di hari kiamat.", "Doa orang-orang yang berlandaskan ilmu pengetahuan."),
        "dua_q_maash_shahidin" to DuaText("Tuliskan Kami Di Antara Saksi", "Ya Tuhan kami, kami telah beriman, maka tulislah kami di antara para saksi.", "Doa orang-orang yang mengetahui kebenaran dan beriman.", "Doa untuk penerimaan iman seseorang."),
        "dua_q_la_tajalna_zalimin" to DuaText("Bukan Dengan Orang-orang yang zalim", "Ya Tuhan kami, jangan tempatkan kami bersama orang-orang yang zalim.", "Doa orang al-A'raf.", "Berlindung dari nasib orang-orang yang zalim."),
        "dua_q_tawaffana_muslimin" to DuaText("Sabar dan Mati sebagai Muslim", "Ya Tuhan kami, curahkan kesabaran atas kami dan matikan kami sebagai Muslim.", "Doa para ahli sihir Fir'aun ketika mereka beriman.", "Sabar dalam pencobaan dan berakhir pada iman."),
        "dua_q_la_tajalna_fitnah" to DuaText("Bukan Ujian bagi Penindas", "Kepada Allah kami bersandar. Ya Tuhan kami, jangan jadikan kami cobaan bagi orang-orang yang zalim, dan peliharalah kami dengan rahmat-Mu dari orang-orang kafir.", "Doa umat Musa (AS).", "Doa untuk penyelamatan dari penindasan dan penindas."),
        "dua_q_nuh_ma_laysa_li" to DuaText("Doa Nuh (AS) Mohon Pengampunan", "Ya Tuhanku, aku berlindung kepada-Mu dari meminta kepada-Mu sesuatu yang tidak aku ketahui. Dan kecuali Engkau mengampuniku dan mengasihaniku, niscaya aku termasuk orang-orang yang merugi.", "Doa taubat Nabi Nuh (AS).", "Pelajaran bertanya dengan sopan santun."),
        "dua_q_mudkhala_sidq" to DuaText("Pintu Masuk dan Keluar Kebenaran", "Ya Tuhanku, izinkan aku masuk dengan kebenaran dan keluar dengan kebenaran, dan berilah aku otoritas pendukung dari diri-Mu.", "Sebelum memasuki tugas, rumah, atau tempat baru.", "Doa yang diajarkan kepada Nabi ﷺ pada masa Hijrah."),
        "dua_q_la_tadharni_fardan" to DuaText("Doa Zakariya (AS) — Jangan Tinggalkan Aku Sendiri", "Ya Tuhanku, jangan tinggalkan aku sendirian, dan Engkaulah pewaris terbaik.", "Bagi mereka yang mencari anak.", "Melalui doa ini Allah mengabulkan Yahya (AS)."),
        "dua_q_munzalan_mubarakan" to DuaText("Tempat Pendaratan yang Diberkati", "Ya Tuhanku, izinkan aku mendarat di tempat pendaratan yang diberkahi, dan Engkaulah sebaik-baik yang membawa ke darat.", "Saat pindah ke rumah baru atau singgah di suatu tempat — doa Nuh (AS).", "Doa memohon berkah di tempat baru."),
        "dua_q_amanna_faghfir" to DuaText("Kami Percaya, Maka Maafkan Kami", "Ya Tuhan kami, kami telah beriman, maka ampunilah kami dan kasihanilah kami, dan Engkaulah sebaik-baik penyayang.", "Doa hamba-hamba Allah yang shaleh.", "Doa komprehensif untuk pengampunan dan belas kasihan."),
        "dua_q_isrif_jahannam" to DuaText("Hindari Hukuman Neraka", "Ya Tuhan kami, jauhkan dari kami siksa Neraka; memang hukumannya selalu melekat. Memang, itu adalah pemukiman dan tempat tinggal yang jahat.", "Doa hamba Yang Maha Penyayang ('Ibad ar-Rahman).", "Doa Al-Qur'an untuk perlindungan dari Neraka."),
        "dua_q_hab_li_hukman" to DuaText("Doa Ibrahim (AS) — Kebijaksanaan dan Jannah", "Ya Tuhanku, berilah aku hikmah dan gabungkan aku dengan orang-orang shaleh, berilah aku sebutan terhormat di kalangan generasi selanjutnya, dan jadikan aku termasuk pewaris Taman Kebahagiaan.", "Meminta hikmah, pergaulan dengan orang-orang shaleh dan surga.", "Doa komprehensif Ibrahim (AS)."),
        "dua_q_lut_najjini_ahli" to DuaText("Doa Luth (AS) — Selamatkan Keluargaku", "Ya Tuhanku, peliharalah aku dan keluargaku dari (akibat) perbuatan mereka.", "Melindungi keluarga dari lingkungan yang jahat.", "Perlindungan keluarga dari kejahatan."),
        "dua_q_sulaiman_awzini" to DuaText("Doa Sulaiman (AS) Ucapan Syukur", "Ya Tuhanku, mampukan aku mensyukuri nikmat-Mu yang Engkau berikan kepadaku dan kedua orang tuaku, dan mengerjakan amal shaleh yang diridhai-Mu, serta memasukkan aku dengan rahmat-Mu ke dalam golongan hamba-hamba-Mu yang saleh.", "Atas kemampuan mensyukuri nikmat.", "Doa Syukur Sulaiman (AS)."),
        "dua_q_musa_zalamtu" to DuaText("Doa Musa (AS) — Aku Menganiaya Diriku Sendiri", "Ya Tuhanku, aku telah bersalah pada diriku sendiri, jadi maafkan aku.", "Pertobatan segera setelah melakukan kesalahan.", "Allah mengampuni Musa (AS)."),
        "dua_q_musa_najjini" to DuaText("Doa Musa (AS) — Selamatkan Aku dari Penindas", "Ya Tuhanku, selamatkan aku dari orang-orang yang zalim.", "Saat takut pada penindas.", "Doa Musa (AS) saat meninggalkan Mesir."),
        "dua_q_lut_unsurni" to DuaText("Doa Luth (AS) — Bantuan Melawan Koruptor", "Ya Tuhanku, bantulah aku melawan orang-orang yang merusak.", "Untuk bantuan terhadap mereka yang menyebarkan korupsi.", "Doa orang-orang yang teguh pada kebenaran."),
        "dua_q_hab_li_salihin" to DuaText("Doa Ibrahim (AS) untuk Anak yang Bertakwa", "Ya Tuhanku, berilah aku (seorang anak) dari kalangan orang-orang shaleh.", "Meminta anak yang shaleh.", "Melalui doa Isma'il (AS) ini terkabul."),
        "dua_q_wasita_kulla_shay" to DuaText("Doa Malaikat Pembawa Arsy", "Ya Tuhan kami, Engkau melingkupi segala sesuatu dengan rahmat dan ilmu, maka ampunilah orang-orang yang bertaubat dan mengikuti jalan-Mu, serta lindungi mereka dari siksa Neraka.", "Para malaikat yang menyandang Arsy memanjatkan doa ini untuk orang-orang yang beriman.", "Dibacakan dengan niat untuk dimasukkan dalam doa para malaikat."),
        "dua_q_ikhwanina" to DuaText("Untuk Saudara-saudara Kita Yang Mendahului Kita", "Ya Tuhan kami, ampunilah kami dan saudara-saudara kami yang mendahului kami dalam keimanan, dan jangan ada rasa dendam dalam hati kami terhadap orang-orang yang beriman. Ya Tuhan kami, Engkau sungguh Maha Baik dan Penyayang.", "Sebuah doa untuk orang-orang beriman yang datang sebelumnya dan untuk hati yang bersih.", "Doa untuk para sahabat yang mulia (RA) dan orang-orang beriman terdahulu."),
        "dua_q_alayka_tawakkalna" to DuaText("Kepadamu Kami Andalkan (Ibrahim AS)", "Ya Tuhan kami, kepadaMu kami bersandar, kepadaMu kami berpaling, dan kepadaMulah kami kembali. Ya Tuhan kami, jangan jadikan kami cobaan bagi orang-orang kafir dan ampunilah kami. Ya Tuhan kami, Engkau sungguh Maha Kuasa lagi Maha Bijaksana.", "Doa Ibrahim (AS) dan para sahabatnya.", "Doa ketergantungan pada Allah dan kembali kepada-Nya."),
        "dua_q_atmim_nurana" to DuaText("Sempurnakan Cahaya Kami", "Our Lord, perfect for us our light and forgive us. Sesungguhnya Engkau Maha Kuasa atas segala sesuatu.", "Doa orang-orang mukmin di hari kiamat.", "Meminta pencerahan pada Sirat."),
        "dua_q_asiya_baytan" to DuaText("Dua Asiya - Sebuah Rumah di Jannah", "Ya Tuhanku, bangunkan untukku di dekat-Mu sebuah rumah di surga, peliharalah aku dari Firaun dan amal-amalnya, dan peliharalah aku dari orang-orang yang zalim.", "Doa Asiya, istri Firaun.", "Allah menjadikannya teladan bagi orang-orang yang beriman."),
        "dua_adhan_response" to DuaText("Menanggapi Adzan", "Tidak ada daya dan kekuatan kecuali dengan izin Allah.", "Ulangi apa yang dikatakan muazin; at 'Hayya 'alas-salah' and 'Hayya 'alal-falah' say this.", "Siapa yang menjawab dari hati maka dia masuk surga."),
        "dua_adhan_shahadah" to DuaText("Setelah Syahadat Muazzin", "Dan aku pun bersaksi bahwa tidak ada yang berhak disembah kecuali Allah, sendiri, tanpa sekutu, dan bahwa Muhammad ﷺ adalah hamba dan utusan-Nya. Aku ridha kepada Allah sebagai Tuhan, kepada Muhammad ﷺ sebagai Rasul, dan kepada Islam sebagai agama.", "Mendengar kesaksian keimanan muazin.", "Dosa-dosanya diampuni."),
        "dua_istiftah_baid" to DuaText("Doa Pembuka: Jauhkan Aku dari Dosa", "Ya Allah, jauhkan aku dari dosa-dosaku sebagaimana Engkau menjauhkan timur dari barat. Ya Allah, bersihkan aku dari dosa-dosa seperti pakaian putih dibersihkan dari kotoran. Ya Allah, hapuslah dosa-dosaku dengan air, salju, dan hujan es.", "Setelah takbir pembukaan (boleh juga diucapkan sebagai pengganti Sana).", "Nabi ﷺ membacakan ini di antara takbir dan bacaan."),
        "dua_hamdan_kathiran" to DuaText("Pujian yang Berlimpah Setelah Ruku", "Ya Tuhan kami, bagi-Mulah puji-pujian, puji-pujian yang berlimpah, suci dan penuh berkah.", "Setelah bangun dari ruku, bersama dengan 'Rabbana lakal-hamd'.", "Lebih dari tiga puluh malaikat berlomba untuk menjadi yang pertama merekamnya."),
        "dua_subbuhun_quddus" to DuaText("Subbuhun Quddus (Ruku & Sujud)", "(Allah) Maha Mulia, Maha Suci, Tuhan para malaikat dan Ruh (Jibril).", "Dalam ruku dan sujud.", "Nabi ﷺ membacakan ini dalam ruku dan sujud."),
        "dua_sujood_dhanbi_kullah" to DuaText("Dalam Sujud: Ampunilah Segala Dosaku", "Ya Allah, ampunilah segala dosaku, baik kecil maupun besar, baik awal maupun akhir, baik yang terang-terangan maupun yang tersembunyi.", "Di sujud.", "Sujud adalah tempat terkabulnya doa."),
        "dua_sujood_ridaka" to DuaText("Berlindung dalam Kesenangan Anda", "Ya Allah, aku berlindung pada ridha-Mu dari murka-Mu, ampunan-Mu dari siksa-Mu, dan aku berlindung pada-Mu dari-Mu. Aku tidak bisa sepenuhnya memuji-Mu; Anda seperti Anda telah memuji diri Anda sendiri.", "Dalam sujud — Aisha (RA) mendengar Nabi ﷺ mengatakan ini.", "Doa sujud Nabi ﷺ."),
        "dua_tashahhud" to DuaText("Tashahhud (At-Tahiyyat)", "Semua ibadah lisan, fisik dan keuangan adalah untuk Allah. Salam sejahtera bagimu wahai Nabi, dan rahmat Allah dan berkah-Nya. Salam sejahtera bagi kami dan hamba-hamba Allah yang shaleh. Aku bersaksi bahwa tidak ada yang berhak disembah kecuali Allah, dan aku bersaksi bahwa Muhammad ﷺ adalah hamba dan utusan-Nya.", "Dalam setiap duduk — diriwayatkan oleh Abdullah bin Mas'ud (RA) (amalan Hanafi).", "Nabi ﷺ mengajarkannya seperti surat Al-Quran."),
    )
}
